   "example": {
    "title": "Путь одной работы",
    "text": "Владелец просит завести работу. Агент ищет похожее в дереве, в GitLab и в задачах групп и называет, где искал. Предпросмотр: тема, короткое имя, код из трёх букв, абзац о работе и ведущий, которого назвал владелец. После согласия в группе темы появляется пустой проект, команда lab кладёт клон на тот же путь в дереве лаборатории и закрывает личные папки. README с «Ведут» уходит первой отправкой прямо в основную ветку, и GitLab сам ставит её защиту, ярлыки и колонки доски. С этого момента любая отправка с ветки открывает предложение на ведущего. Старая папка проекта переезжает навыком lab-knowledge: утверждения предложением, заметки и логи в закрытые папки того же клона."
   },
